/** partKey → 所属功能模块：取 key 首段；不存在于模块表返回 null */
function partModuleOf(partKey: string): string | null {
  const key = partKey.split('/')[0];
  return MODULE_SUBS[key] !== undefined ? key : null;
}

/** 换下旧件时的耐久（0-100）：按所属功能模块有效耐久比取整；无对应模块默认 100 */
function partDuraOf(partKey: string): number {
  const store = useDataStore();
  const key = partModuleOf(partKey);
  if (!key) return 100;
  const mods = store.data.模块 as unknown as Record<string, ModuleData>;
  const d = moduleDura(mods, key);
  if (d.最大耐久 <= 0) return 100;
  return Math.round((d.当前耐久 / d.最大耐久) * 100);
}

/**
 * 更换部件时，把换下的旧件写入物品库存（可再装 / 可去维修店卖）。
 * - 目录无此名定义时自动写玩家定义（类型=部件），保证物品页可见；
 * - 旧件耐久 = 换下时所属功能模块耐久比（卖出按耐久折价）。
 */
export function moveOldPartToInventory(partKey: string, newName: string): void {
  const store = useDataStore();
  const old = partOf(partKey).型号;
  if (!old || old === newName) return;
  const oldDef = mergedItems()[old];
  const def = {
    类型: '部件',
    部位: partKey.split('/')[0],
    价格: oldDef?.价格 ?? 0,
    效果: oldDef?.效果 ?? '换下的旧部件',
  };
  ensurePlayerDef(old, def);
  const it = store.data.物品[old];
  const du = partDuraOf(partKey);
  if (it) {
    it.数量 = (it.数量 ?? 0) + 1;
    it.耐久 = du;
  } else {
    store.data.物品[old] = { 类型: '部件', 数量: 1, 价格: def.价格, 效果: def.效果, 耐久: du };
  }
}
