/**
 * 剧情触发信号（storyEvents）
 * ------------------------------------------------------------
 * 前端只在「关键行为」发生时推送一次性信号，真实剧情由角色卡 AI 消费：
 *   - 进入地图地点（含维修店）→ kind:'visit'
 *   - 维修店维修 / 预约排队 → kind:'repair'
 *   - 更换部件 → kind:'replace'
 *   - 换段 / 换素体 → kind:'swap_seg' | 'swap_body'
 *   - 购买送修服务 → kind:'delivery'
 *
 * 储存：localStorage 键 `机损营业中:story_event`（JSON 数组，最多保留 20 条）。
 * 角色卡脚本可在剧情编排前读该键并消费（读取后建议清除或标记已消费）。
 * 预览环境 / 真实酒馆环境均可用；该键独立于角色 schema，便于 AI 层存取。
 */

export interface StoryEvent {
  kind: 'visit' | 'repair' | 'replace' | 'swap_seg' | 'swap_body' | 'delivery';
  place?: string;        // 地点名（visit 用）
  mode?: 'self' | 'delivery'; // 维修店到店模式
  module?: string;       // 维修/更换的功能模块
  part?: string;         // 旧部件
  newPart?: string;      // 新部件
  fee?: number;          // 花费
  days?: number;         // 排队天数（repair 用）
  ts: number;            // 触发时间戳
}

const STORAGE_KEY = '机损营业中:story_event';
const MAX_KEEP = 20;

export function pushStoryEvent(e: Omit<StoryEvent, 'ts'>): void {
  try {
    const list = readStoryEvents();
    list.push({ ...e, ts: Date.now() });
    while (list.length > MAX_KEEP) list.shift();
    localStorage.setItem(STORAGE_KEY, JSON.stringify(list));
  } catch {
    /* 预览环境 localStorage 不可用时静默降级 */
  }
}

export function readStoryEvents(): StoryEvent[] {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return [];
    const arr = JSON.parse(raw);
    return Array.isArray(arr) ? arr : [];
  } catch {
    return [];
  }
}

export function lastStoryEvent(): StoryEvent | null {
  const list = readStoryEvents();
  return list.length ? list[list.length - 1] : null;
}
