/** 特殊部件归属覆盖：bone-spine（机械骨骼部件）→ 电子脑.脊椎 */
export const PART_SUB_OVERRIDE: Record<string, { module: string; sub: string }> = {
  'bone-spine': { module: '电子脑', sub: '脊椎' },
};

/** 装饰件（不可点、无详情）：手部触感传感单元 p54 / p54-m */
export const DECORATIVE_PARTS: string[] = ['p54', 'p54-m'];

export interface Dura {
  当前耐久: number;
  最大耐久: number;
}

/** 模块数据形状（与 schema 模块项对齐） */
export interface ModuleData {
  当前耐久: number;
  最大耐久: number;
  子项?: Record<string, Dura>;
}

/** 解析模块键（历史旧键 → 新键） */
function resolveKey(module: string): string {
  return MODULE_KEY_ALIAS[module] ?? module;
}

/** 读取单个子项耐久（own 从本模块子项取；ref 从源模块/源子项取） */
export function subDura(moduleData: Record<string, ModuleData>, module: string, def: SubItemDef): Dura {
  if (def.kind === 'ref' && def.refModule) {
    const src = moduleData[resolveKey(def.refModule)];
    if (!src) return { 当前耐久: 100, 最大耐久: 100 };
    if (def.refSub) return src.子项?.[def.refSub] ?? { 当前耐久: src.当前耐久, 最大耐久: src.最大耐久 };
    return { 当前耐久: src.当前耐久, 最大耐久: src.最大耐久 };
  }
  // own：数据存于本模块.子项[子项名]
  const self = moduleData[resolveKey(module)];
  if (!self) return { 当前耐久: 100, 最大耐久: 100 };
  return self.子项?.[def.name] ?? { 当前耐久: self.当前耐久, 最大耐久: self.最大耐久 };
}

/** 模块是否有子目录 */
export function hasSubs(module: string): boolean {
  return !!MODULE_SUBS[module]?.length;
}

/** 模块有效耐久（有子项 = 子项精确均值四舍五入取整；无子项 = 模块自身耐久） */
export function moduleDura(moduleData: Record<string, ModuleData>, module: string): Dura {
  const subs = MODULE_SUBS[module];
  if (subs?.length) {
    const du = subs.map(s => subDura(moduleData, module, s));
    const valid = du.filter(d => d.最大耐久 > 0);
    if (!valid.length) return { 当前耐久: 0, 最大耐久: 100 };
    const sum = valid.reduce((a, b) => a + b.当前耐久 / b.最大耐久, 0);
    const avg = (sum / valid.length) * 100;
    return { 当前耐久: Math.round(avg), 最大耐久: 100 };
  }
  const m = moduleData[resolveKey(module)];
  return m ? { 当前耐久: m.当前耐久, 最大耐久: m.最大耐久 } : { 当前耐久: 100, 最大耐久: 100 };
}

/** 根据部件 id 定位到（模块, 子项）——点击内部部件时使用 */
export function locatePart(moduleData: Record<string, ModuleData>, id: string, module: string, subItem?: string): { module: string; sub: string | null } {
  if (DECORATIVE_PARTS.includes(id)) return { module, sub: null };
  const ov = PART_SUB_OVERRIDE[id];
  if (ov) return { module: ov.module, sub: ov.sub };
  const key = resolveKey(module);
  if (subItem && MODULE_SUBS[key]?.some(s => s.name === subItem)) return { module: key, sub: subItem };
  return { module: key, sub: null };
}
