const DEFAULT_LIB = { format: 'items/v1', player: {}, disabled: [] };
const lib = useLocalStorage('机损营业中:item_lib', DEFAULT_LIB);
/** 合并目录：官方 + 玩家（玩家同名覆盖官方） */
export function mergedItems() {
    return { ...BUILTIN_ITEMS, ...lib.value.player };
}
/** 服装占用的穿着位置列表：单件给 string，连体/连衣裙等多槽给 string[]；无穿着位置返回空数组 */
export function 穿着位置们(def) {
    const v = def?.穿着位置;
    if (!v)
        return [];
    return Array.isArray(v) ? [...v] : [v];
}
/** 玩家自定义条目的名称列表（含覆盖官方同名的条目） */
export function playerNames() {
    return Object.keys(lib.value.player);
}
export function itemDef(name) {
    return mergedItems()[name];
}
/** 购买来源：缺省 = 仅网购（兼容旧定义） */
export function shopSources(name) {
    const def = itemDef(name);
    return def?.购买来源 ?? ['网购'];
}
/** 维修店售价（缺省 = 价格；实际结算再 × 难度倍率） */
export function shopPriceOf(name) {
    const def = itemDef(name);
    return def?.维修店价 ?? def?.价格 ?? 0;
}
/**
 * 保障换下旧件可显示：目录中无此名定义时，自动写入一条玩家定义
 * （类型=部件、部位、价格、效果），使旧件进入物品页库存后可见、可再装、可售卖。
 * 目录已有定义（官方或玩家）时不重复写入。
 */
export function ensurePlayerDef(name, def) {
    if (name in mergedItems())
        return;
    lib.value.player[name] = { ...def };
}
export function isItemEnabled(name) {
    return !lib.value.disabled.includes(name);
}
export function setItemEnabled(name, on) {
    const i = lib.value.disabled.indexOf(name);
    if (on && i >= 0)
        lib.value.disabled.splice(i, 1);
    if (!on && i < 0)
        lib.value.disabled.push(name);
}
/** 新增 / 覆盖玩家自定义条目 */
export function addItem(name, def) {
    lib.value.player[name] = { ...def };
}
export function removeItem(name) {
    delete lib.value.player[name];
    const i = lib.value.disabled.indexOf(name);
    if (i >= 0)
        lib.value.disabled.splice(i, 1);
}
/** 导出完整目录（含官方快照，便于分享 / 归档） */
export function exportItemsJson() {
    return JSON.stringify({ format: 'items/v1', official: BUILTIN_ITEMS, player: lib.value.player, disabled: lib.value.disabled }, null, 2);
}
/**
 * 导入目录。官方条目以代码版本为准（永不覆盖）。
 * @param mode merge     合并：玩家条目并入（同名覆盖现有玩家定义，含官方同名 = 玩家覆盖）
 *              overwrite 覆盖：player 整体替换为导入内容（官方仍以代码为准）
 *              add-only  仅新增：只添加当前不存在的名称，不覆盖任何现有玩家定义
 */
export function importItemsJson(json, mode = 'merge') {
    try {
        const data = JSON.parse(json);
        if (!data || data.format !== 'items/v1')
            throw new Error('格式不符（需 items/v1）');
        let n = 0;
        const incoming = data.player && typeof data.player === 'object' ? data.player : {};
        const valid = {};
        for (const [name, def] of Object.entries(incoming)) {
            if (!name || typeof name !== 'string' || !def || typeof def !== 'object')
                continue;
            valid[name] = { ...def };
        }
        if (mode === 'overwrite') {
            lib.value.player = valid;
            n = Object.keys(valid).length;
        }
        else {
            for (const [name, def] of Object.entries(valid)) {
                if (mode === 'add-only' && name in lib.value.player)
                    continue;
                lib.value.player[name] = def;
                n += 1;
            }
        }
        if (Array.isArray(data.disabled)) {
            for (const d of data.disabled) {
                if (typeof d === 'string' && !lib.value.disabled.includes(d))
                    lib.value.disabled.push(d);
            }
        }
        const modeLabel = mode === 'merge' ? '合并' : mode === 'overwrite' ? '覆盖' : '仅新增';
        return { ok: true, message: `导入成功：${modeLabel} ${n} 条玩家条目（官方条目不覆盖）` };
    }
    catch (err) {
        return { ok: false, message: `导入失败：${err.message}` };
    }
}
/** 批量启用 / 停用（names 为空 = 作用于全部官方条目） */
export function setManyEnabled(names, on) {
    const pool = names.length ? names : Object.keys(BUILTIN_ITEMS);
    for (const name of pool) {
        const i = lib.value.disabled.indexOf(name);
        if (on && i >= 0)
            lib.value.disabled.splice(i, 1);
        if (!on && i < 0)
            lib.value.disabled.push(name);
    }
}
/** 恢复官方默认：删除所有玩家对官方同名条目的覆盖，并把官方条目全部恢复启用 */
export function resetOfficialDefaults() {
    let removed = 0;
    for (const name of Object.keys(BUILTIN_ITEMS)) {
        if (name in lib.value.player) {
            delete lib.value.player[name];
            removed += 1;
        }
        const i = lib.value.disabled.indexOf(name);
        if (i >= 0)
            lib.value.disabled.splice(i, 1);
    }
    return removed;
}
