const STORAGE_KEY = '机损营业中:parts';

function loadOverrides(): Record<string, PartDef> {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return {};
    const data = JSON.parse(raw);
    return data && typeof data === 'object' && data.overrides ? (data.overrides as Record<string, PartDef>) : {};
  } catch {
    return {};
  }
}

/** 玩家/官方覆盖项（reactive：创意工坊编辑后机体页即时刷新） */
export const partOverrides = reactive<Record<string, PartDef>>(loadOverrides());

export function saveParts() {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify({ overrides: { ...partOverrides } }));
  } catch {
    /* 存储失败静默（不白屏） */
  }
}

/** 读取部件：覆盖项优先 → 内置 → 占位回退 */
export function partOf(key: string): PartDef {
  const o = partOverrides[key];
  if (o) return o;
  const b = BUILTIN[key];
  if (b) return b;
  return {
    型号: '原厂组件 · 型号待补充',
    介绍: '当前为原厂默认部件；更换部件后，此处显示新部件的型号与说明。',
  };
}

/** 全部可配置的部件 key（内置 + 覆盖项去重） */
export function partKeys(): string[] {
  return [...new Set([...Object.keys(BUILTIN), ...Object.keys(partOverrides)])];
}

/** 保存/新增一个部件覆盖条目 */
export function setPart(key: string, def: PartDef) {
  partOverrides[key] = { ...def, source: 'player' };
  saveParts();
}

/** 恢复默认：删除覆盖项（回到内置原厂件） */
export function resetPart(key: string) {
  delete partOverrides[key];
  saveParts();
}

/** 导出覆盖项 JSON（供创意工坊导出/备份） */
export function exportPartsJson(): string {
  return JSON.stringify({ format: 'parts/v1', overrides: { ...partOverrides } }, null, 2);
}

/** 导入覆盖项 JSON：只接受 parts/v1 格式，逐条校验后写入 */
export function importPartsJson(text: string): { ok: boolean; message: string } {
  try {
    const data = JSON.parse(text);
    if (!data || data.format !== 'parts/v1' || !data.overrides) {
      return { ok: false, message: '格式不符：需要 parts/v1 且包含 overrides' };
    }
    const src = data.overrides as Record<string, PartDef>;
    let count = 0;
    for (const [k, v] of Object.entries(src)) {
      if (!k || typeof v !== 'object' || !v || typeof v.型号 !== 'string' || typeof v.介绍 !== 'string') continue;
      partOverrides[k] = { 型号: v.型号, 介绍: v.介绍, 效果: typeof v.效果 === 'string' ? v.效果 : undefined, source: 'player' };
      count += 1;
    }
    saveParts();
    return { ok: true, message: `已导入 ${count} 条部件配置` };
  } catch {
    return { ok: false, message: 'JSON 解析失败' };
  }
}
